values
  ('f04ef58b-f75d-50be-85a2-f80fa0a4c00e', 'Varun', 35, 'Marketing by profession, storyteller by habit. I''m happiest with dancing, good company and a bit of live music. Good listener, better storyteller.', array['Tech', 'Dogs', 'Dancing', 'Art', 'Stand-up comedy', 'Live music']::text[], 'relationship', 27, 45, 'demo/avatars/001.svg', 28.69, 77.22, now() - interval '3137 minutes', true, now() - interval '466 hours', true),
